param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'decimal-comparison-format-interfaces-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('DecimalThrowingProvider'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$builder=$assembly.DefineDynamicModule('Main').DefineType('ThrowingProvider',[Reflection.TypeAttributes]'Public,Sealed');$builder.AddInterfaceImplementation([IFormatProvider]);$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public)|Out-Null;$method=$builder.DefineMethod('GetFormat',[Reflection.MethodAttributes]'Public,Virtual,Final,HideBySig,NewSlot',[object],[type[]]@([type]));$il=$method.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'provider failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$builder.DefineMethodOverride($method,[IFormatProvider].GetMethod('GetFormat'));$throwing=[Activator]::CreateInstance($builder.CreateType())
$custom=[Globalization.NumberFormatInfo]::new();$custom.NegativeSign='~';$custom.PositiveSign='^';$custom.NumberDecimalSeparator='@';$custom.NumberGroupSeparator='_';$custom.NumberGroupSizes=[int[]]@(2,3);$custom.CurrencySymbol='USD';$custom.CurrencyDecimalSeparator=':';$custom.CurrencyGroupSeparator="'";$custom.CurrencyGroupSizes=[int[]]@(3,2);$custom.CurrencyPositivePattern=2;$custom.CurrencyNegativePattern=14;$custom.NumberNegativePattern=4;$custom.PercentSymbol='%!'
$comparable=[IComparable].GetMethod('CompareTo',[type[]]@([object]));$formattable=[IFormattable].GetMethod('ToString',[type[]]@([string],[IFormatProvider]));$comparisons=[Collections.Generic.List[object]]::new();$formats=[Collections.Generic.List[object]]::new()
for($index=0;$index -lt $plan.bits.Count;$index++){$value=[decimal]::new([int[]]$plan.bits[$index]);$others=[Collections.Generic.List[object]]::new();for($right=0;$right -lt $plan.bits.Count;$right++){$others.Add([pscustomobject]@{kind='decimal';index=$right;value=[decimal]::new([int[]]$plan.bits[$right])})};foreach($kind in $plan.otherKinds){$other=$null;switch($kind){'int32'{$other=[int]1};'int64'{$other=[long]1};'double'{$other=[double]1};'string'{$other='1'};'object'{$other=[object]::new()};'bool'{$other=$true}};$others.Add([pscustomobject]@{kind=$kind;index=-1;value=$other})}
 foreach($other in $others){$arguments=[object[]]::new(1);$arguments[0]=$other.value;try{$actual=[int]$comparable.Invoke($value,$arguments);$result=[ordered]@{ok=$true;value=$actual}}catch{$result=Failure $_};$comparisons.Add([ordered]@{index=$index;kind=$other.kind;right=$other.index;result=$result;afterBits=[decimal]::GetBits($value)})}
 foreach($format in $plan.formats){foreach($profile in $plan.providers){$provider=$null;switch($profile){'invariant'{$provider=[Globalization.NumberFormatInfo]::InvariantInfo};'custom'{$provider=$custom};'throwing'{$provider=$throwing}};$arguments=[object[]]::new(2);$arguments[0]=$format;$arguments[1]=$provider;try{$actual=[string]$formattable.Invoke($value,$arguments);$result=[ordered]@{ok=$true;textUnits=[int[]][char[]]$actual}}catch{$result=Failure $_};$formats.Add([ordered]@{index=$index;format=$format;provider=$profile;result=$result;afterBits=[decimal]::GetBits($value)})}}
}
if($comparisons.Count -ne 228 -or $formats.Count -ne 960){throw 'Wrong Decimal dispatch matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';interfaces=[ordered]@{comparable=[IComparable].IsAssignableFrom([decimal]);formattable=[IFormattable].IsAssignableFrom([decimal])};comparisons=$comparisons.ToArray();formats=$formats.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 20 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS Decimal interface dispatch: 228 comparisons, 960 formats and immutable input snapshots'
